  T["kapitel-bearbeiten"]={html:"<h2 class=\"sr-only\">{{t:ui.chapter_edit_a11y}}</h2>\n<style>\n.gw-f label{display:block;font-size:13px;font-weight:500;color:var(--text-primary);margin-bottom:4px}\n.gw-f .hint{font-size:12px;color:var(--text-muted);font-weight:400}\n.gw-f input,.gw-f textarea,.gw-f select{width:100%;box-sizing:border-box;padding:9px 12px;border:0.5px solid var(--border-strong);border-radius:var(--radius);background:var(--surface-2);color:var(--text-primary);font:inherit;font-size:14px}\n.gw-f input:focus,.gw-f textarea:focus,.gw-f select:focus{outline:none;border-color:var(--border-accent)}\n.gw-f textarea{resize:vertical;line-height:1.6}\n.gw-err{font-size:13px;color:var(--text-danger);margin-top:4px}\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n</style>\n<div style=\"padding:1rem 0\">\n  <form class=\"gw-f\" id=\"gw-kapitel-bearbeiten\" data-chapter=\"{{CHAPTER_ID}}\" data-num=\"{{CHAPTER_NUMBER}}\" novalidate style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-pencil\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">{{t:ui.edit_chapter}}</span>\n    </div>\n    <div>\n      <label for=\"gw-title\">{{t:ui.title}}</label>\n      <input id=\"gw-title\" value=\"{{CHAPTER_TITLE}}\" placeholder=\"{{t:ui.chapter_title}}\">\n      <div class=\"gw-err\" id=\"gw-title-err\" hidden>{{t:ui.please_enter_a_title}}</div>\n    </div>\n    <div>\n      <label for=\"gw-subtitle\">{{t:ui.subtitle}} <span class=\"hint\">{{t:ui.optional}}</span></label>\n      <input id=\"gw-subtitle\" value=\"{{CHAPTER_SUBTITLE}}\">\n    </div>\n    <div>\n      <label for=\"gw-summary\">{{t:ui.summary}} <span class=\"hint\">{{t:ui.a_short_chapter_summary}}</span></label>\n      <textarea id=\"gw-summary\" rows=\"2\">{{CHAPTER_SUMMARY}}</textarea>\n    </div>\n    <div>\n      <label for=\"gw-goal\">{{t:ui.chapter_goal}} <span class=\"hint\">{{t:ui.what_should_the_reader_understand_afterwards}}</span></label>\n      <textarea id=\"gw-goal\" rows=\"2\">{{CHAPTER_GOAL}}</textarea>\n    </div>\n    <div style=\"display:flex;justify-content:flex-end;gap:var(--gap-sm);border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">{{t:ui.cancel}}</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">{{t:ui.save}}</button>\n    </div>\n  </form>\n</div>\n",run:function(tr){
function gwSend(text,action,data){var d=GW.withHead(action,data||{}),k=Object.keys(d),short=k.every(function(x){var v=d[x];return typeof v==='number'||typeof v==='boolean'||(typeof v==='string'&&/^[^\s`]{1,80}$/.test(v));});sendPrompt(short?text+'\n\n`gw:'+action+k.map(function(x){return ' '+x+'='+d[x];}).join('')+'`':text+'\n\n```gw\n'+JSON.stringify(Object.assign({action:action},d))+'\n```');}
(function(){
  var f=document.getElementById('gw-kapitel-bearbeiten');
  var $=function(id){return document.getElementById(id);};
  var id=f.dataset.chapter,num=f.dataset.num;
  var title=$('gw-title'),err=$('gw-title-err');
  title.addEventListener('input',function(){err.hidden=true;});
  function lock(){f.querySelectorAll('input,textarea,button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    if(!title.value.trim()){err.hidden=false;title.focus();return;}
    var g=function(k){return $(k).value.trim();};
    var d={chapter_id:id,title:g('gw-title'),subtitle:g('gw-subtitle'),summary:g('gw-summary'),goal:g('gw-goal')};
    lock();
    gwSend(tr("ui.save_chapter",{number:num,title:d.title}),'chapter.update',d);
  });
  $('gw-cancel').addEventListener('click',function(){lock();gwSend(tr("ui.editing_chapter_cancelled",{number:num}),'form.cancel',{form:'chapter.update',chapter_id:id});});
})();

}};
